# Keep the public API unchanged

def deep_transform(data):
    """Return a list of (key, value) tuples for positive numeric values."""
    result = []
    for group in data:
        if not isinstance(group, list):
            continue
        for item in group:
            if not isinstance(item, dict):
                continue
            result.extend(_process_item(item))
    return result

# Helper that processes a single dict

def _process_item(item):
    out = []
    for key in sorted(item):
        value = item[key]
        if isinstance(value, (int, float)):
            out.append((key, value if value > 0 else 0))
    return out
